const fields = ["name", "email", "phone", "card", "exp", "cvc", "captcha"];
let state = null;
let deadline = 0;
let warned = false;
let expiredAnnounced = false;
let paymentLocked = false;
let paymentKey = null;
let assisted = false;
let complete = false;

async function api(path, data) {
  const response = await fetch("/api/checkout" + path, {
    method: data === undefined ? "GET" : "POST",
    credentials: "same-origin",
    cache: "no-store",
    headers: data === undefined ? {} : {
      "Content-Type": "application/json",
      "X-CSRF-Token": state?.csrf || ""
    },
    body: data === undefined ? undefined : JSON.stringify(data)
  });
  if (!response.ok) throw new Error("Request failed");
  return response.json();
}

function applyTime(data) {
  state = { ...state, ...data };
  // 서버 시각 차이를 보정하고, 이후에는 단조 증가 시계를 사용한다.
  // 화면 시계는 안내용이다. 실제 만료 판정은 언제나 서버가 수행한다.
  deadline = performance.now() +
    Math.max(0, Date.parse(data.expiresAt) - Date.parse(data.now));
  warned = false;
  expiredAnnounced = false;
  tick();
}

function active() {
  return !!state && (state.paused || performance.now() < deadline);
}

function tick() {
  if (!state || complete) return;
  const seconds = Math.max(0, Math.ceil((deadline - performance.now()) / 1000));
  $("clock").textContent = state.paused ? "일시정지" :
    `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;

  $("extend").disabled = paymentLocked || state.paused ||
    seconds === 0 || state.extensionsLeft <= 0;
  $("extend").textContent = `2분 연장 (${state.extensionsLeft}회 남음)`;
  $("reserve").hidden = active() || paymentLocked;
  $("review-button").disabled = !active() || paymentLocked;
  $("pay").disabled = !active() || paymentLocked;

  if (!state.paused && !paymentLocked && seconds > 0 &&
      seconds <= 40 && !warned) {
    warned = true;
    $("time-status").textContent = state.extensionsLeft > 0
      ? "40초 이하 남았습니다. 계속 입력하려면 ‘2분 연장’을 눌러 주세요."
      : "40초 이하 남았습니다. 연장 횟수를 모두 사용했습니다. 만료돼도 입력은 유지됩니다.";
  }

  if (!state.paused && !paymentLocked && seconds === 0 && !expiredAnnounced) {
    expiredAnnounced = true;
    $("time-status").textContent =
      "좌석 선점이 만료되었습니다. 입력은 유지했습니다. 같은 좌석을 다시 선점한 뒤 진행해 주세요.";
  }
}
setInterval(tick, 500);

async function load() {
  $("reload").hidden = true;
  $("service-status").textContent = "예매 정보를 불러오는 중입니다.";
  try {
    const data = await api("");
    applyTime(data);
    assisted = !!data.captcha.verified;
    $("captcha").required = !assisted;
    $("captcha").disabled = assisted;
    $("captcha-image").src = data.captcha.imageUrl;
    $("captcha-image").hidden = assisted;
    $("captcha-audio").src = data.captcha.audioUrl;
    $("captcha-audio").hidden = assisted;
    $("assist").disabled = assisted;
    $("service-status").textContent = "예매 정보를 불러왔습니다.";
  } catch {
    $("service-status").textContent =
      "예매 정보를 확인하지 못했습니다. 입력은 가능하지만 연결 확인 전에는 결제할 수 없습니다.";
    $("reload").hidden = false;
  }
}
$("reload").onclick = load;

async function changeTime(path, successMessage) {
  try {
    applyTime(await api(path, {}));
    $("time-status").textContent = successMessage;
  } catch {
    $("time-status").textContent =
      "좌석 시간을 변경하지 못했습니다. 현재 선점 상태를 확인하거나 다시 시도해 주세요.";
  }
}
$("extend").onclick = () => changeTime("/extend", "좌석 선점 시간이 2분 연장되었습니다.");
$("reserve").onclick = () => changeTime("/reserve", "같은 좌석을 다시 선점했습니다.");

$("assist").onclick = async () => {
  $("assist").disabled = true;
  try {
    const data = await api("/assistance", {});
    applyTime(data);
    // 상담 주소는 서버의 동일 출처 허용 경로로 제한한다.
    const url = new URL(data.supportUrl, location.origin);
    if (url.origin !== location.origin) throw new Error("Invalid URL");
    $("assist-link").href = url.href;
    $("assist-options").hidden = false;
    $("assist-status").textContent =
      "서버에서 좌석 시간을 일시정지했습니다. 문자 상담을 열어 인증해 주세요.";
    $("assist-link").focus();
  } catch {
    $("assist").disabled = false;
    $("assist-status").textContent =
      "상담 연결 상태를 확인하지 못했습니다. 시간 정지를 가정하지 말고 다시 시도해 주세요.";
  }
};

$("assist-check").onclick = async () => {
  try {
    const data = await api("/assistance");
    applyTime(data);
    if (!data.verified) {
      $("assist-status").textContent = "아직 상담 인증이 완료되지 않았습니다.";
      return;
    }
    assisted = true;
    $("captcha").required = false;
    $("captcha").disabled = true;
    $("captcha").value = "";
    clearError("captcha");
    $("captcha-image").hidden = true;
    $("captcha-audio").pause();
    $("captcha-audio").hidden = true;
    $("assist-status").textContent = "상담 인증이 완료되었습니다. 보안문자 입력은 필요 없습니다.";
  } catch {
    $("assist-status").textContent = "인증 상태를 확인하지 못했습니다. 다시 확인해 주세요.";
  }
};

function clearError(id) {
  $(id).removeAttribute("aria-invalid");
  $(id + "-error").textContent = "";
}
function showErrors(errors) {
  const list = $("error-list");
  list.replaceChildren();
  for (const [id, message] of Object.entries(errors)) {
    if (!fields.includes(id)) continue;
    $(id).setAttribute("aria-invalid", "true");
    $(id + "-error").textContent = message;
    const li = document.createElement("li");
    const a = document.createElement("a");
    a.href = "#" + id;
    a.textContent = message;
    a.onclick = event => {
      event.preventDefault();
      $(id).focus();
    };
    li.append(a);
    list.append(li);
  }
  $("error-summary").hidden = !list.children.length;
  if (list.children.length) $("error-summary").focus();
}
function validate() {
  fields.forEach(clearError);
  const errors = {};
  $("name").value = $("name").value.trim();
  $("email").value = $("email").value.trim();

  if (!$("name").value) errors.name = "이름을 입력해 주세요.";
  if (!$("email").value) errors.email = "티켓을 받을 이메일을 입력해 주세요.";
  else if (!$("email").validity.valid)
    errors.email = "이메일을 name@example.com 형식으로 입력해 주세요.";

  const number = $("card").value.replace(/[\s-]/g, "");
  if (!/^\d{12,19}$/.test(number))
    errors.card = "카드 번호를 확인해 주세요. 숫자와 공백·하이픈만 사용할 수 있습니다.";

  const expiry = $("exp").value.replace(/\s/g, "");
  if (!/^(0[1-9]|1[0-2])\/?\d{2}$/.test(expiry))
    errors.exp = "유효기간을 08/29 또는 0829처럼 입력해 주세요.";

  if (!/^\d{3,4}$/.test($("cvc").value))
    errors.cvc = "카드 보안 코드 숫자 3~4자리를 입력해 주세요.";

  if (!assisted && !$("captcha").value.trim())
    errors.captcha = "보안문자를 입력하거나 상담 인증을 완료해 주세요.";

  showErrors(errors);
  return Object.keys(errors).length === 0;
}

let suggestedEmail = "";
$("email").addEventListener("blur", () => {
  const address = $("email").value.trim();
  const at = address.lastIndexOf("@");
  const corrections = {
    "gmial.com": "gmail.com",
    "gamil.com": "gmail.com",
    "naver.con": "naver.com"
  };
  const replacement = corrections[address.slice(at + 1).toLowerCase()];
  suggestedEmail = at > 0 && replacement ? address.slice(0, at + 1) + replacement : "";
  $("email-suggestion").hidden = !suggestedEmail;
  $("email-suggestion").textContent = suggestedEmail
    ? `혹시 ${suggestedEmail}인가요? 이 주소로 변경` : "";
});
$("email-suggestion").onclick = () => {
  $("email").value = suggestedEmail;
  $("email-suggestion").hidden = true;
  clearError("email");
  $("email").focus();
};

function reviewItem(label, value) {
  const dt = document.createElement("dt");
  const dd = document.createElement("dd");
  dt.textContent = label;
  dd.textContent = value;
  $("review-data").append(dt, dd);
}
$("booking").onsubmit = event => {
  event.preventDefault();
  if (!validate()) return;
  if (!active()) {
    $("time-status").textContent = "진행하려면 좌석을 다시 선점해 주세요.";
    return;
  }
  $("review-data").replaceChildren();
  reviewItem("공연", state.order.title);
  reviewItem("좌석", state.order.seats);
  reviewItem("총 결제 금액", state.order.totalText);
  reviewItem("취소·환불 핵심 조건", state.order.refundSummary);
  reviewItem("예매자", $("name").value);
  reviewItem("티켓 수신 이메일", $("email").value);
  reviewItem("휴대폰", $("phone").value || "입력하지 않음");
  reviewItem("카드", "끝 네 자리 " + $("card").value.replace(/[\s-]/g, "").slice(-4));
  reviewItem("뉴스레터", $("news").checked ? "수신 동의" : "동의하지 않음");
  $("pay").textContent = `${state.order.totalText} 결제하기`;
  $("entry").hidden = true;
  $("review").hidden = false;
  $("review-title").focus();
};
$("edit").onclick = () => {
  if (paymentLocked) return;
  $("review").hidden = true;
  $("entry").hidden = false;
  $("page-title").focus();
};

function showResult(message, allowCheck) {
  $("result").hidden = false;
  $("result-message").textContent = message;
  $("check-payment").hidden = !allowCheck;
  $("result-title").focus();
}

function handlePayment(data) {
  if (data.status === "paid") {
    complete = true;
    fields.forEach(id => { $(id).value = ""; });
    $("booking").hidden = true;
    $("extend").disabled = true;
    $("clock").textContent = "예매 완료";
    showResult("결제가 완료되었습니다. 예매 내역에서 티켓과 수신 이메일을 확인할 수 있습니다.", false);
    return;
  }
  if (data.status === "rejected") {
    paymentLocked = false;
    paymentKey = null;
    $("edit").disabled = false;
    $("review").hidden = true;
    $("entry").hidden = false;
    showResult(data.message || "결제가 승인되지 않았습니다. 입력을 확인해 주세요.", false);
    showErrors(data.errors || {});
    tick();
    return;
  }
  showResult(
    "결제 결과가 아직 확정되지 않았습니다. 새 결제는 차단했습니다. 결과 확인 버튼이나 예매 내역을 이용해 주세요.",
    true
  );
}

$("pay").onclick = async () => {
  if (paymentLocked || !active()) return;
  paymentLocked = true;
  paymentKey = crypto.randomUUID();
  $("edit").disabled = true;
  tick();

  showResult("결제 결과를 확인하고 있습니다. 다시 결제하지 마세요.", false);
  try {
    const data = await api("/pay", {
      idempotencyKey: paymentKey,
      name: $("name").value,
      email: $("email").value,
      phone: $("phone").value.trim(),
      card: $("card").value.replace(/[\s-]/g, ""),
      exp: $("exp").value.replace(/\s/g, ""),
      cvc: $("cvc").value,
      captcha: assisted ? "" : $("captcha").value.trim(),
      news: $("news").checked
    });
    handlePayment(data);
  } catch {
    // 통신 실패는 결제 실패가 아니다. 중복 결제를 허용하지 않는다.
    showResult(
      "통신이 끊겨 결제 결과를 확인하지 못했습니다. 새 결제는 차단했습니다. 결제 결과를 다시 확인해 주세요.",
      true
    );
  }
};

$("check-payment").onclick = async () => {
  $("check-payment").disabled = true;
  try {
    handlePayment(await api("/payment-status?key=" + encodeURIComponent(paymentKey)));
  } catch {
    $("result-message").textContent =
      "결제 결과를 아직 확인하지 못했습니다. 다시 확인하거나 예매 내역을 이용해 주세요.";
  } finally {
    $("check-payment").disabled = false;
  }
};

load();
</script>
</body>
</html>
